{
  "technical_and_design_decisions": [
    "Use the Spring Boot Security starter to provide Basic Auth functionality.",
    "Default the 'server.basic.enabled' property to false in application.yml.",
    "Use 'servers.yml' as the configuration file for single-user security overrides.",
    "Update the Spring Boot dependency to the latest RELEASE version, superseding the snapshot requirement.",
    "Build Docker images using Dockerfiles based on Ubuntu OS with Java 7.x."
  ],
  "assumptions": [
    "The XD Shell is a separate module that requires modifications to accept new command-line arguments.",
    "The spike for the REST API (U6) involves only planning, documentation, and story creation, not actual implementation.",
    "The necessary base Docker images (Ubuntu, Java 7) are available or can be easily configured.",
    "1 workday equals 8 hours of effort.",
    "The 'spring-xd-dirt' project is accessible and its build system (e.g., Maven/Gradle) is understood."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Update Spring Boot Dependency",
      "activity_description": "Update the project dependencies to pull in the latest Spring Boot RELEASE version to inherit OOTB security features (covers U4 and U5).",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A2",
      "activity_name": "Implement Basic Auth Option",
      "activity_description": "Add the Spring Boot security starter dependency to the spring-xd-dirt project and configure the 'server.basic.enabled' property in application.yml with a default value of false (covers U1).",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A3",
      "activity_name": "Implement Single-User Security Configurations",
      "activity_description": "Enable the ability to provide single-user security configurations through the 'servers.yml' file to allow overrides as needed (covers U2).",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A4",
      "activity_name": "Update XD Shell for Security Credentials",
      "activity_description": "Add '--username' and '--password' options to the admin config command in the XD Shell to allow interaction with secured xd admin servers (covers U3).",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A5",
      "activity_name": "REST API Push Archive Spike",
      "activity_description": "Conduct a spike to assess customer requirements, brainstorm and document options, socialize with the team, identify phases, and create new stories for a REST API to push archives with custom module definitions (covers U6).",
      "most_likely_effort": 3.0
    },
    {
      "activity_id": "A6",
      "activity_name": "Create Sandbox Docker Image",
      "activity_description": "Create a Dockerfile and build a sandbox Docker image containing Ubuntu OS, Full XD Jar, Java 7.x, Redis, and RabbitMQ for experimentation (covers U7).",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "A7",
      "activity_name": "Create Production-Ready Docker Image",
      "activity_description": "Create a Dockerfile and build a production-ready Docker image containing Ubuntu OS, Full XD Jar, and Java 7.x to serve as a baseline for deployment (covers U8).",
      "most_likely_effort": 1.5
    }
  ],
  "reported_total": {
    "most_likely_effort": 11.5
  }
}
